<section class="planning-page" data-ai-page aria-labelledby="ai-title">
    <header class="workspace-header"><div><h1 id="ai-title">AI assistant</h1><p>A thinking partner for your next steps. You review every change before it's saved.</p></div><span class="permission-badge"><svg class="ui-icon" aria-hidden="true"><use href="#icon-lock"/></svg>You're in control</span></header>
    <p class="field-error is-hidden" data-planning-error role="alert"></p>
    <div class="planning-grid">
        <section class="planning-panel"><h2>Request a proposal</h2><form class="stack-form" data-ai-form><div class="field"><label for="ai-capability">Capability</label><select id="ai-capability" name="capability"><option value="help_plan">Help me plan</option><option value="suggest_goals">Suggest goals</option><option value="suggest_milestones">Suggest milestones</option><option value="suggest_tasks">Suggest tasks</option><option value="review_goal">Review a goal</option><option value="review_task">Review a task</option><option value="break_down_goal">Break a goal into a plan</option><option value="draft_review">Draft review reflections</option></select></div><fieldset class="context-picker"><legend>Context allowed to be sent</legend><p class="subtle-copy">Only items you select may be referenced by AI or used when applying the proposal.</p><div data-ai-context aria-live="polite"><p>Loading available context…</p></div><p data-ai-context-summary>No context selected.</p></fieldset><div class="field"><label for="ai-instruction">Instructions</label><textarea id="ai-instruction" name="instruction" maxlength="5000" required></textarea></div><label class="check-row"><input type="checkbox" name="consent" required><span>I agree to send my instructions and selected context to Google Gemini. The free tier may use data to improve products; Notes and files are not sent by default.</span></label><button class="button button-primary" type="submit">Generate proposal</button></form></section>
        <section class="planning-panel"><h2>Proposal awaiting review</h2><div data-ai-proposal><p>No proposal yet.</p></div><div class="section-heading is-hidden" data-ai-actions><button class="button button-primary" type="button" data-ai-apply>Apply</button><button class="button button-quiet" type="button" data-ai-reject>Reject</button></div></section>
    </div>
</section>
